<?php
declare(strict_types=1);
namespace App\Modules\Tourism\Models;
use App\Core\Database;
final class TourismRoom{private Database $db;public function __construct(){$this->db=app()->get('db');}public function find(int $t,int $id,bool $d=false):?array{$w=$d?'deleted_at IS NOT NULL':'deleted_at IS NULL';return $this->db->fetch("SELECT * FROM tourism_stay_room_types WHERE tenant_id=? AND id=? AND {$w} LIMIT 1",[$t,$id]);}public function create(int $t,int $stay,array $d,int $u):int{$this->db->execute("INSERT INTO tourism_stay_room_types(uuid,tenant_id,stay_id,name,description,bed_type,max_guests,quantity,price_per_night,status,created_by,updated_by) VALUES(UUID(),?,?,?,?,?,?,?,?,?,?,?)",[$t,$stay,$d['name'],$d['description'],$d['bed_type'],$d['max_guests'],$d['quantity'],$d['price_per_night'],$d['status'],$u,$u]);return (int)$this->db->lastInsertId();}public function update(int $t,int $id,array $d,int $u):void{$this->db->execute("UPDATE tourism_stay_room_types SET name=?,description=?,bed_type=?,max_guests=?,quantity=?,price_per_night=?,status=?,updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$d['name'],$d['description'],$d['bed_type'],$d['max_guests'],$d['quantity'],$d['price_per_night'],$d['status'],$u,$t,$id]);}public function delete(int $t,int $id,int $u):void{$this->db->execute("UPDATE tourism_stay_room_types SET deleted_at=NOW(),updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$u,$t,$id]);}public function restore(int $t,int $id,int $u):void{$this->db->execute("UPDATE tourism_stay_room_types SET deleted_at=NULL,updated_by=? WHERE tenant_id=? AND id=?",[$u,$t,$id]);}}
